let showcaseIndex=0,showcasePaused=false,showcaseTimer=null,showcaseHovered=false,showcaseFocused=false;const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
function pauseIcon(){return showcasePaused||motionPreference.matches?'<svg width="13" height="13" viewBox="0 0 14 14" fill="none" aria-hidden="true"><path d="M4 2.5L11 7L4 11.5V2.5Z" fill="currentColor"/></svg>':'<svg width="13" height="13" viewBox="0 0 14 14" fill="none" aria-hidden="true"><path d="M4 3V11M10 3V11" stroke="currentColor" stroke-width="1.8"/></svg>'}
function updateShowcase(){const scene=strategyScenes[showcaseIndex];document.querySelectorAll('.strategy-scene').forEach((e,i)=>e.classList.toggle('active',i===showcaseIndex));document.querySelectorAll('[data-scene]').forEach(e=>{const selected=Number(e.dataset.scene)===showcaseIndex;e.classList.toggle('active',selected);e.setAttribute('aria-pressed',String(selected))});document.querySelector('#showcase-title').textContent=scene.title;document.querySelector('#showcase-description').textContent=scene.description;document.querySelector('#try-strategy').textContent=scene.action;const pause=document.querySelector('#pause-showcase');pause.innerHTML=pauseIcon();pause.setAttribute('aria-label',showcasePaused?'Resume rotation':'Pause rotation');pause.setAttribute('aria-pressed',String(showcasePaused));pause.hidden=motionPreference.matches;document.querySelector('#showcase').classList.toggle('disengaged',showcasePaused)}
function stopShowcaseTimer(){if(showcaseTimer!==null)clearInterval(showcaseTimer);showcaseTimer=null}
function startShowcaseTimer(){stopShowcaseTimer();if(showcasePaused||showcaseHovered||showcaseFocused||motionPreference.matches||document.hidden||document.querySelector('#showcase').hidden)return;showcaseTimer=setInterval(()=>{showcaseIndex=(showcaseIndex+1)%strategyScenes.length;updateShowcase()},7500)}
function chooseScene(index){showcaseIndex=index;updateShowcase();startShowcaseTimer()}
function syncShowcase(hasPortfolio){document.querySelector('#showcase').hidden=hasPortfolio;document.querySelector('#portfolio').hidden=!hasPortfolio;document.querySelector('#save').hidden=!hasPortfolio;if(hasPortfolio){showcaseHovered=false;showcaseFocused=false;stopShowcaseTimer()}else startShowcaseTimer()}
function initShowcase(){document.querySelector('#showcase-stage').innerHTML=strategyScenes.map((s,i)=>'<div class="strategy-scene '+(i===0?'active':'')+'">'+s.svg+'</div>').join('');updateShowcase();document.querySelectorAll('[data-scene]').forEach(e=>e.onclick=()=>chooseScene(Number(e.dataset.scene)));document.querySelector('#pause-showcase').onclick=()=>{showcasePaused=!showcasePaused;updateShowcase();startShowcaseTimer()};document.querySelector('#try-strategy').onclick=()=>{send(strategyScenes[showcaseIndex].prompt);if(innerWidth<=760)mobile('work')};document.querySelector('#showcase').addEventListener('mouseenter',()=>{showcaseHovered=true;stopShowcaseTimer()});document.querySelector('#showcase').addEventListener('mouseleave',()=>{showcaseHovered=false;startShowcaseTimer()});document.querySelector('#showcase').addEventListener('focusin',()=>{showcaseFocused=true;stopShowcaseTimer()});document.querySelector('#showcase').addEventListener('focusout',e=>{if(!document.querySelector('#showcase').contains(e.relatedTarget)){showcaseFocused=false;startShowcaseTimer()}});document.addEventListener('visibilitychange',startShowcaseTimer);motionPreference.addEventListener('change',()=>{updateShowcase();startShowcaseTimer()})}
